    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = R * 0.14; ctx.stroke(); }
  } else if (kind === 'soviet') {
    // Gold star with sickle arc (stylised)
    ctx.fillStyle = fg;
    ctx.beginPath();
    const r = R * 0.4;
    for (let i = 0; i < 10; i++) {
      const ang = -Math.PI / 2 + (i * Math.PI) / 5, rad = i % 2 === 0 ? R : r;
      const x = cx + Math.cos(ang) * rad, y = cy + Math.sin(ang) * rad;
