    pole.position.y = 2.4; pole.castShadow = true;
    g.add(pole);
    const finial = new THREE.Mesh(new THREE.SphereGeometry(0.3, 8, 6), new THREE.MeshLambertMaterial({ color: 0x8f7a3a, emissive: 0x241a05 }));
    finial.position.y = 4.9;
    g.add(finial);
