    ctx.fillRect(44, 8, 40, 112); ctx.fillRect(8, 44, 112, 40);
    ctx.strokeRect(44, 8, 40, 112); ctx.strokeRect(8, 44, 112, 40);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  decalCache[side] = tex;
  return tex;
}

