}
.faction-card.selected .fc-check { opacity: 1; }
.fc-check svg { width: 13px; height: 13px; }

#alliance-presets { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.alliance-preset {
  background: var(--panel-2); border: 1px solid var(--line); border-radius: 4px;
  padding: 8px 9px; text-align: left; display: flex; flex-direction: column; gap: 2px;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.alliance-preset:hover { border-color: var(--line-strong); }
.alliance-preset.selected { border-color: var(--brass); background: linear-gradient(180deg, rgba(214,178,94,0.13), transparent); box-shadow: 0 0 12px rgba(214, 178, 94, 0.16); }
.ap-name { font-size: 10px; letter-spacing: 1.2px; color: var(--brass); font-weight: 600; text-transform: uppercase; }
.ap-desc { font-size: 8.5px; color: var(--dim); line-height: 1.4; }
.wr-custom-btn {
  margin-top: 8px; width: 100%;
  background: none; border: 1px dashed var(--line-strong); color: var(--brass);
  padding: 8px 10px; letter-spacing: 1.6px; font-size: 9px; text-transform: uppercase; border-radius: 4px;
  transition: background 0.15s, border-color 0.15s;
}
.wr-custom-btn:hover { background: rgba(214, 178, 94, 0.08); }
.wr-custom-btn.open { background: rgba(214, 178, 94, 0.1); border-style: solid; }
#custom-alliances { margin-top: 10px; display: flex; flex-direction: column; gap: 5px; }
.custom-row { display: flex; align-items: center; gap: 8px; background: rgba(0,0,0,0.28); padding: 4px 7px; border-radius: 4px; }
.cr-flag { width: 42px; height: 28px; border-radius: 2px; border: 1px solid rgba(0,0,0,0.5); }
.cr-name { flex: 1; font-size: 10px; letter-spacing: 1px; color: var(--text); }
.cr-seg { display: flex; gap: 4px; }
.cr-btn {
  width: 40px; height: 24px; border: 1px solid var(--line); background: var(--panel-3);
  border-radius: 3px; font-family: var(--font-mono); font-size: 9px; color: var(--dim);
  transition: border-color 0.15s, color 0.15s;
}
.cr-btn:hover { border-color: var(--line-strong); }
.cr-btn.selected { border-color: var(--brass); color: var(--brass); background: rgba(214, 178, 94, 0.16); }
.wr-alliance-note { margin-top: 8px; font-size: 9px; color: #6d6c60; font-style: italic; line-height: 1.5; }

/* Sandbox hides skirmish-only controls */
#menu.mode-sandbox #wr-faction-section,
#menu.mode-sandbox #diff-row,
#menu.mode-sandbox #diff-label { display: none; }

/* ---------- HUD additions ---------- */
#faction-badge canvas { display: block; border-radius: 3px; border: 1px solid var(--line-strong); }
.pip-owned { box-shadow: 0 0 10px rgba(255,255,255,0.22); }
.timer-sandbox { font-size: 13px !important; letter-spacing: 2px; color: var(--brass) !important; }
.feed-usa { border-left-color: #9dc08b; }
.feed-ussr { border-left-color: #e07a5a; }
.feed-germany { border-left-color: #d0d0d0; }
.feed-japan { border-left-color: #ffb060; }
.feed-france { border-left-color: #6aa8ff; }

/* ---------- Build tabs & fort grid ---------- */
#build-tabs { display: flex; gap: 4px; justify-content: center; margin: 6px 0 6px; flex-wrap: wrap; }
.build-tab {
  background: var(--panel-3); border: 1px solid var(--line); border-bottom: none;
  border-radius: 3px 3px 0 0; color: var(--dim);
  font-size: 8px; letter-spacing: 1.5px; padding: 6px 12px 5px;
  transition: color 0.15s, border-color 0.15s;
}
.build-tab.selected { color: var(--brass); border-color: var(--brass); background: rgba(214,178,94,0.1); }
#fort-grid {
  display: grid; grid-template-columns: repeat(6, 1fr); gap: 5px;
  max-height: 172px; overflow-y: auto; padding: 2px;
}
.fort-btn {
  background: linear-gradient(180deg, #26281f, #1a1b15);
  border: 1px solid var(--line); border-radius: 4px;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 6px 2px 5px; transition: border-color 0.15s, box-shadow 0.15s;
}
.fort-btn:hover { border-color: var(--brass); box-shadow: 0 0 10px rgba(214,178,94,0.16); }
.fort-btn.disabled { opacity: 0.4; }
.fort-icon { color: var(--brass); display: block; }
.fort-icon svg { width: 22px; height: 22px; }
.fort-name { font-size: 6.8px; text-align: center; line-height: 1.25; color: var(--text); min-height: 17px; }
.fort-cost { font-family: var(--font-mono); font-size: 8.5px; color: var(--brass); }

'''
css = css[:start] + new_menu + css[end:]
with open('css/style.css', 'w') as f:
    f.write(css)
print('menu section replaced OK')
EOF

